import re
from pathlib import Path
p=Path('native/stdo-store/releases/v2.5.1-rc.1/standards/STDO_REFERENCE_FRAME_BASELINE.md');lines=p.read_text().splitlines()
slugs={'derived-end-to-end-interface-integration-frame','interface-integration-claim-boundaries','interface-integration-obligations','interface-integration-qualification','computational-whole-path-evaluation','executive-attention-evaluation-and-action'}
heads=[]
for i,line in enumerate(lines):
 m=re.match(r'"'^(#{1,6}) (.+)'"',line)
 if m:heads.append((i,len(m[1]),re.sub(r'["'^'"\\w\\- ]','',m[2].lower()).replace(' ','-')))
for i,level,slug in heads:
 if slug in slugs:
